-- ============================================================
-- Migration: Property & Tenant Isolation Remediation
-- Date: 2026-06-24
-- 
-- Standardizes dual-layer tenant and property isolation across all tables.
-- ============================================================

BEGIN;

-- 1. Create user_has_tenant_access helper function
CREATE OR REPLACE FUNCTION user_has_tenant_access(user_uuid UUID, tenant_uuid UUID)
RETURNS BOOLEAN AS $$
DECLARE
    u_scope user_scope;
    u_tenant_id UUID;
BEGIN
    -- Get user's scope and tenant_id
    SELECT scope, tenant_id INTO u_scope, u_tenant_id FROM users WHERE id = user_uuid;
    
    -- Platform admins can access any tenant
    IF u_scope IN ('super_admin', 'platform_admin') THEN
        RETURN TRUE;
    END IF;
    
    -- Tenant users can only access their own tenant
    RETURN u_tenant_id = tenant_uuid;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Overload to support TEXT tenant_id columns automatically
CREATE OR REPLACE FUNCTION user_has_tenant_access(user_uuid UUID, tenant_uuid TEXT)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN user_has_tenant_access(user_uuid, tenant_uuid::UUID);
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 2. Redefine user_has_property_access to be scope-aware
CREATE OR REPLACE FUNCTION user_has_property_access(user_uuid UUID, property_uuid UUID, required_level VARCHAR DEFAULT 'read')
RETURNS BOOLEAN AS $$
DECLARE
    has_access BOOLEAN;
    u_scope user_scope;
BEGIN
    -- Check user scope (platform admins bypass check)
    SELECT scope INTO u_scope FROM users WHERE id = user_uuid;
    IF u_scope IN ('super_admin', 'platform_admin') THEN
        RETURN TRUE;
    END IF;

    -- Check direct property access
    SELECT EXISTS (
        SELECT 1 FROM user_property_access upa
        WHERE upa.user_id = user_uuid
        AND upa.property_id = property_uuid
        AND (upa.expires_at IS NULL OR upa.expires_at > NOW())
        AND (
            upa.access_level = required_level
            OR upa.access_level = 'admin'
            OR (required_level = 'read' AND upa.access_level IN ('write', 'manage'))
            OR (required_level = 'write' AND upa.access_level = 'manage')
        )
    ) INTO has_access;
    
    IF has_access THEN
        RETURN TRUE;
    END IF;

    -- Check group-level access
    SELECT EXISTS (
        SELECT 1 FROM user_group_access uga
        JOIN properties p ON p.group_id = uga.group_id
        WHERE uga.user_id = user_uuid
        AND p.id = property_uuid
        AND (uga.expires_at IS NULL OR uga.expires_at > NOW())
    ) INTO has_access;

    RETURN has_access;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Overload to support TEXT property_id columns automatically
CREATE OR REPLACE FUNCTION user_has_property_access(user_uuid UUID, property_uuid TEXT, required_level VARCHAR DEFAULT 'read')
RETURNS BOOLEAN AS $$
BEGIN
    RETURN user_has_property_access(user_uuid, property_uuid::UUID, required_level);
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

