-- 5. Backfill structural entities and default fallbacks
--    Properties gets tenant_id from property_groups
UPDATE properties p SET tenant_id = pg.tenant_id FROM property_groups pg WHERE p.group_id = pg.id AND p.tenant_id IS NULL;

-- Final backfill fallback for any remaining NULL values
DO $$
DECLARE
    r RECORD;
    def_tenant UUID;
    def_property UUID := '00000000-0000-0000-0000-000000000001';
BEGIN
    -- Find platform tenant or first available tenant
    SELECT id INTO def_tenant FROM tenants WHERE subdomain = 'platform';
    IF def_tenant IS NULL THEN
        SELECT id INTO def_tenant FROM tenants ORDER BY created_at ASC LIMIT 1;
    END IF;

    IF def_tenant IS NOT NULL THEN
        FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE' LOOP
            -- Backfill tenant_id
            IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = r.table_name AND column_name = 'tenant_id') THEN
                EXECUTE format('UPDATE %I SET tenant_id = %L WHERE tenant_id IS NULL', r.table_name, def_tenant);
            END IF;

            -- Backfill property_id
            IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = r.table_name AND column_name = 'property_id') THEN
                EXECUTE format('UPDATE %I SET property_id = %L WHERE property_id IS NULL', r.table_name, def_property);
            END IF;
        END LOOP;
    END IF;
END $$;

-- 6. Set NOT NULL constraints where appropriate
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE' LOOP
        -- Exclude tables where tenant_id is allowed to be NULL
        IF r.table_name NOT IN ('users', 'property_groups', 'tenants', 'plans', 'currencies', 'supported_languages', 'system_config', 'system_defaults') THEN
            IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = r.table_name AND column_name = 'tenant_id') THEN
                BEGIN
                    EXECUTE format('ALTER TABLE %I ALTER COLUMN tenant_id SET NOT NULL', r.table_name);
                EXCEPTION WHEN OTHERS THEN
                    RAISE NOTICE 'Could not set tenant_id NOT NULL on table %', r.table_name;
                END;
            END IF;
        END IF;

        -- Exclude tables where property_id is allowed to be NULL
        IF r.table_name NOT IN ('properties', 'property_groups', 'tenants', 'plans', 'currencies', 'supported_languages', 'system_config', 'system_defaults', 'users', 'roles', 'user_roles', 'permissions', 'role_permissions', 'sessions', 'biometric_credentials', 'password_history', 'two_factor_pending', 'token_blacklist') THEN
            IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = r.table_name AND column_name = 'property_id') THEN
                BEGIN
                    EXECUTE format('ALTER TABLE %I ALTER COLUMN property_id SET NOT NULL', r.table_name);
                EXCEPTION WHEN OTHERS THEN
                    RAISE NOTICE 'Could not set property_id NOT NULL on table %', r.table_name;
                END;
            END IF;
        END IF;
    END LOOP;
END $$;

-- 7. Helper function to apply dual-scoping isolation policy dynamically
CREATE OR REPLACE FUNCTION apply_dual_isolation(target_table TEXT)
RETURNS VOID AS $$
DECLARE
    has_tenant BOOLEAN;
    has_property BOOLEAN;
BEGIN
    -- Exclude system tables
    IF target_table IN ('tenants', 'plans', 'currencies', 'supported_languages', 'system_config', 'system_defaults') THEN
        RETURN;
    END IF;

    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = target_table AND column_name = 'tenant_id') INTO has_tenant;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = target_table AND column_name = 'property_id') INTO has_property;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = target_table AND table_type = 'BASE TABLE') THEN
        EXECUTE 'ALTER TABLE ' || target_table || ' ENABLE ROW LEVEL SECURITY';
        EXECUTE 'DROP POLICY IF EXISTS ' || target_table || '_isolation ON ' || target_table;
        EXECUTE 'DROP POLICY IF EXISTS ' || target_table || '_property_isolation ON ' || target_table;
        
        IF has_tenant AND has_property THEN
            EXECUTE 'CREATE POLICY ' || target_table || '_isolation ON ' || target_table || 
                    ' FOR ALL USING (user_has_tenant_access(auth.uid(), tenant_id) AND user_has_property_access(auth.uid(), property_id))';
        ELSIF has_tenant THEN
            EXECUTE 'CREATE POLICY ' || target_table || '_isolation ON ' || target_table || 
                    ' FOR ALL USING (user_has_tenant_access(auth.uid(), tenant_id))';
        ELSIF has_property THEN
            EXECUTE 'CREATE POLICY ' || target_table || '_isolation ON ' || target_table || 
                    ' FOR ALL USING (user_has_property_access(auth.uid(), property_id))';
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Apply dual-scoping to all base tables dynamically
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE' LOOP
        PERFORM apply_dual_isolation(r.table_name);
    END LOOP;
END $$;

-- Clean up helpers
DROP FUNCTION apply_dual_isolation(TEXT);


    -- Enable RLS
    ALTER TABLE IF EXISTS supported_languages ENABLE ROW LEVEL SECURITY;
    ALTER TABLE IF EXISTS system_config ENABLE ROW LEVEL SECURITY;

    -- Drop old policies
    DROP POLICY IF EXISTS supported_languages_read ON supported_languages;
    DROP POLICY IF EXISTS supported_languages_write ON supported_languages;
    DROP POLICY IF EXISTS system_config_read ON system_config;
    DROP POLICY IF EXISTS system_config_write ON system_config;

    -- Create public/authenticated select policies
    CREATE POLICY supported_languages_read ON supported_languages FOR SELECT USING (true);
    CREATE POLICY system_config_read ON system_config FOR SELECT USING (true);

    -- Create write policies for service role and platform admin
    CREATE POLICY supported_languages_write ON supported_languages FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY system_config_write ON system_config FOR ALL TO service_role USING (true) WITH CHECK (true);
  
COMMIT;
